from itertools import combinations, product
import heapq


def dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        ordered = names if name_order == "ascending" else names[::-1]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            rows = {row["version"]: row for row in packages[name]}
            choices.append([None] + sorted(rows))

        best_key = None
        best_versions = None
        for assignment in product(*choices):
            selected = {name: version for name, version in zip(names, assignment)
                        if version is not None}
            if any(version in blocked.get(name, []) or
                   (name in pins and pins[name] != version)
                   for name, version in selected.items()):
                continue
            if any(name not in selected or not bounds[0] <= selected[name] <= bounds[1]
                   for name, bounds in data["roots"].items()):
                continue

            edges = {}
            valid = True
            for name, version in selected.items():
                row = next(r for r in packages[name] if r["version"] == version)
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                edges[name] = []
                for dep in deps:
                    other = dep["name"]
                    edges[name].append(other)
                    if (other not in selected or
                            not dep["min"] <= selected[other] <= dep["max"]):
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(selected):
                continue

            state, cyclic = {}, False
            def visit(name):
                nonlocal cyclic
                if state.get(name) == 1:
                    cyclic = True
                    return
                if state.get(name) == 2:
                    return
                state[name] = 1
                for other in edges.get(name, []):
                    visit(other)
                state[name] = 2
            for name in selected:
                visit(name)
            if cyclic:
                continue

            vector = tuple(selected.get(name, -1) for name in ordered)
            key = vector if preference == "maximum" else tuple(-x for x in vector)
            if best_key is None or key > best_key:
                best_key, best_versions = key, selected
        return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}
    return solve


def ledger(data):
    def rounded(n, d):
        if data["rounding"] == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    events = data["events"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(events):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    eligible = [j for j in jobs if j["id"] not in blocked]
    if not mandatory.issubset({j["id"] for j in eligible}):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for subset in combinations(eligible, k):
        ids = tuple(sorted(j["id"] for j in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        # Half-open intervals: intervals ending at t do not overlap those starting at t.
        points = sorted({j["start"] for j in subset} | {j["end"] for j in subset})
        if any(sum(j["start"] <= t < j["end"] for j in subset) > 2 for t in points):
            continue
        value = sum(j["value"] for j in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit.get(start_node, 0)
    start_time = data["start"]
    initial = (start_node, start_mask, data["coupons"])
    dist = {initial: start_time}
    queue = [(start_time, start_node, start_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            dest = edge["v"]
            next_mask = mask | bit.get(dest, 0)
            durations = [(edge["duration"], coupons)]
            if coupons:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = (dest, next_mask, remaining)
                if arrival < dist.get(nxt, float("inf")):
                    dist[nxt] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": dependency_solver("maximum", "descending"),
    "component_02": dependency_solver("minimum", "descending"),
    "component_03": dependency_solver("maximum", "ascending"),
    "component_04": dependency_solver("minimum", "ascending"),
    "component_05": dependency_solver("maximum", "descending"),
    "component_06": ledger,
    "component_07": quota_intervals,
    "component_08": temporal_routes,
}
